import assert from 'node:assert/strict';
import {test} from 'node:test';
import {latestState, readState, renderMigration} from '../src/migration.ts';
import {emptyState, type State} from '../src/snapshot.ts';

const state: State = {version: 1, functions: {'public.f()': {drop: 'DROP FUNCTION IF EXISTS "f"();', hash: 'abc', signature: '{}'}}, triggers: {}};

test('renderMigration separates statements with breakpoints and ends with the state', () => {
	assert.equal(renderMigration(['SELECT 1;', 'SELECT 2;'], state), [
		'-- Generated by drizzle-triggers from your pgFunction() and pgTrigger() definitions.',
		'SELECT 1;',
		'--> statement-breakpoint',
		'SELECT 2;',
		`-- drizzle-triggers:state ${JSON.stringify(state)}`,
		'',
	].join('\n'));
});

test('readState reads the state back, and nothing from other migrations', () => {
	assert.deepEqual(readState(renderMigration(['SELECT 1;'], state).replaceAll('\n', '\r\n')), state);
	assert.equal(readState('CREATE TABLE "users" ();'), undefined);
	assert.equal(readState(`SELECT '-- drizzle-triggers:state {}';`), undefined, 'the marker only counts at the start of a line');
	assert.deepEqual(readState(`-- drizzle-triggers:state ${JSON.stringify(state)}`), state);
});

test('readState rejects a state it does not understand', () => {
	for (const value of [{version: 2, functions: {}, triggers: {}}, {version: 1, functions: null, triggers: {}}, {version: 1, functions: {}, triggers: null}, {version: 1, functions: {}}, null]) {
		assert.throws(() => readState(`-- drizzle-triggers:state ${JSON.stringify(value)}`), /Unsupported drizzle-triggers state/);
	}

	assert.throws(() => readState('SELECT 1;\n-- drizzle-triggers:state {"version":1,\n'), /Unsupported drizzle-triggers state, was the migration edited by hand\? \{"version":1,$/);
});

test('latestState takes the newest migration with a state, and reads no further', () => {
	const older = renderMigration(['SELECT 1;'], emptyState);
	const newer = renderMigration(['SELECT 2;'], state);
	assert.deepEqual(latestState(['CREATE TABLE "x" ();', newer, older]), state);
	assert.deepEqual(latestState([older, newer]), emptyState);
	assert.equal(latestState(['CREATE TABLE "x" ();']), undefined);

	const read: string[] = [];
	function* migrations() {
		for (const migration of ['CREATE TABLE "x" ();', newer, 'never read']) {
			read.push(migration);
			yield migration;
		}
	}

	assert.deepEqual(latestState(migrations()), state);
	assert.equal(read.length, 2);
});
